<script setup lang="ts">
import {computed,reactive,toRefs} from 'vue'
import ClientNavigation from './ClientNavigation.vue'
import ClientPageState from './ClientPageState.vue'
import ClientAssetTabs from './ClientAssetTabs.vue'
import ClientDialog from './ClientDialog.vue'
import ClientPaymentMethods from './ClientPaymentMethods.vue'
import {isClientPreview} from '../lib/api'
import {paymentState,paymentStates,paymentMethod,paymentProvider,refundAmount,orderKind,type ConsumerOrder} from '../lib/order-display'
import type {ConsumerOrdersModel} from '../lib/use-consumer-orders'
const props=defineProps<{model:ConsumerOrdersModel;packages?:boolean}>()
const {switchReason,switchIntent,requiresSwitch,payLabel,guest,consumerLogin,methods,methodsAction,methodsError,balanceCents,paying,querying,payError,paymentUnknown,canPay,rechargeOrder,readMethods,payCurrent,queryCurrent,demo,toggleDemo,detailTarget,detailData,detailAction,detailError,panel,method,openDetails,closeDetails,readDetails,switchPanel,orderStates,states,rows,page,loadAction,error,selected,reason,submitting,formError,history,historyOrder,historyBusy,historyError,retryHistory,closeHistory,status,filters,load,filter,open,cancel,submit,readHistory,turn,time,money,confirmation,paymentAction,actionError,notice,requestAction,closeAction,confirmAction}=toRefs(reactive(props.model))
const tabs=computed(()=>filters.value.map(item=>({id:item.value,label:item.label})))
const displayState=computed(()=>paying.value?'processing':paymentUnknown.value?'unknown':switchIntent.value?.phase==='waiting'?'switching':detailData.value?paymentState(detailData.value):'unknown'),result=computed(()=>paymentStates[displayState.value])
const targetMethod=computed(()=>switchIntent.value&&detailData.value?paymentMethod({...detailData.value,method:switchIntent.value.provider}):'')
const listLoading=computed(()=>!!loadAction.value&&['initial','mode'].includes(loadAction.value)||loadAction.value?.startsWith('filter:'))
const icon=(name:string)=>(import.meta.env.UNI_PLATFORM==='h5'?'/h5-assets':'')+'/static/decoration/framework/icons/'+name+'-blue.svg'
const statusLabel=(order:ConsumerOrder)=>order.demo&&order.paymentState?paymentStates[order.paymentState].title:orderStates.value[order.status]||'处理中'
const paymentLabel=(order:ConsumerOrder)=>order.paymentState==='processing'||order.paymentState==='unknown'?'查看支付状态':'继续支付'
const number=(order:ConsumerOrder)=>order.number||order.id
const amountLabel=(order:ConsumerOrder)=>order.payerTotalCents!=null?'实付金额':order.status==='pending'?'应付金额':'订单金额'
</script>
<template>
 <view class="consumer-orders">
  <ClientNavigation :title="packages?'历史套餐订单':'订单中心'" back :fallback="packages?'/pages/member/index':'/pages/profile/index'"/>
  <view v-if="isClientPreview&&!packages" class="preview-mode"><text>{{demo?'演示数据':'站点订单'}}</text><button role="button" :loading="loadAction==='mode'" :disabled="!!loadAction||submitting||!!paymentAction||!!selected||!!confirmation" @click="toggleDemo">{{demo?'切换站点订单':'切换演示数据'}}</button></view>
  <ClientAssetTabs :model-value="status" :items="tabs" label="订单状态" dense :loading="loadAction?.startsWith('filter:')?loadAction.slice(7):''" :disabled="submitting||!!paymentAction||!!selected||!!confirmation" @update:model-value="filter"/>
  <scroll-view enhanced class="orders-scroll" scroll-y :show-scrollbar="false"><view class="order-body">
   <view v-if="notice" class="order-notice" role="status">{{notice}}</view>
   <ClientPageState v-if="guest" :title="packages?'登录后查看历史套餐订单':'登录后查看我的订单'" description="查看订单进度、付款状态和售后记录" @action="consumerLogin"/>
   <view v-if="error" class="order-error" role="alert"><text>{{error}}</text><button role="button" :loading="loadAction==='retry'" :disabled="submitting||!!loadAction" @click="load('retry')">重新加载</button></view>
   <view v-else-if="listLoading" class="order-empty" role="status">正在读取订单…</view>
   <template v-else>
    <view v-for="order in rows.items" :key="order.id" class="order-card">
     <view class="order-heading"><view class="order-kind"><image :src="icon(order.kind==='balance_recharge'?'wallet':order.kind==='points_recharge'?'coins':'receipt-text')" mode="aspectFit"/><text>{{packages?'历史套餐订单':orderKind(order)}}</text></view><text class="order-status" :class="order.status">{{statusLabel(order)}}</text></view>
     <view class="order-purchase"><text class="order-name">{{order.name}}</text><view class="order-price"><text>¥</text>{{money(order.payerTotalCents??order.amountCents)}}</view></view>
     <view class="order-meta"><text>{{time(order.createdAt)}}</text><text>{{amountLabel(order)}}</text></view>
     <view v-if="order.afterSale" class="order-sale-state">{{states[order.afterSale.state]||'售后处理中'}}</view>
     <view class="order-actions">
      <button role="button" class="detail-entry" :disabled="submitting||!!paymentAction||!!confirmation||!!selected" @click="openDetails(order)">查看详情</button>
      <button v-if="order.canDelete&&!demo" role="button" :disabled="!!paymentAction||submitting||!!loadAction||!!selected" @click="requestAction(order,'delete')">删除订单</button>
      <button v-if="order.status==='pending'&&!demo" role="button" :disabled="!!paymentAction||submitting||!!loadAction||!!selected" @click="requestAction(order,'cancel')">取消订单</button>
      <button v-if="order.status==='pending'" role="button" class="primary" :disabled="submitting||!!paymentAction||!!selected||!!confirmation" @click="openDetails(order,'payment')">{{paymentLabel(order)}}</button>
      <button v-if="order.canApply&&!demo" role="button" :disabled="submitting" @click="open(order)">{{order.afterSale?.state==='REJECTED'?'重新申请售后':'申请退款'}}</button>
      <button v-if="order.afterSale&&!demo" role="button" :disabled="submitting" @click="readHistory(order)">售后记录</button>
     </view>
    </view>
    <view v-if="!rows.items.length&&!error&&!guest" class="order-empty" role="status"><image :src="icon('receipt-text')" mode="aspectFit"/><text>{{packages?'暂无历史套餐订单':'暂无相关订单'}}</text><text class="empty-note">订单记录会显示在这里</text></view>
   </template>
   <view v-if="rows.total>rows.pageSize||page>1" class="pager"><button role="button" :loading="loadAction==='page:previous'" :disabled="page<=1||!!loadAction||submitting" @click="turn(-1)">上一页</button><text>{{page}} / {{Math.max(1,Math.ceil(rows.total/rows.pageSize))}}</text><button role="button" :loading="loadAction==='page:next'" :disabled="page*rows.pageSize>=rows.total||!!loadAction||submitting" @click="turn(1)">下一页</button></view>
  </view></scroll-view>
  <ClientDialog v-if="panel&&detailTarget" :title="panel==='detail'?'订单详情':'支付状态'" presentation="sheet" :busy="paying||querying" @close="closeDetails">
   <view v-if="detailError" class="order-error" role="alert"><text>{{detailError}}</text><button role="button" :loading="detailAction==='retry'" :disabled="!!detailAction" @click="readDetails('retry')">重新加载</button></view>
   <view v-if="detailAction&&!detailData&&!detailError" class="sheet-loading" role="status">正在读取订单…</view>
   <template v-if="detailData">
    <view v-if="detailData.demo" class="sheet-demo">演示订单</view>
    <template v-if="panel==='detail'">
     <view class="detail-summary"><text class="detail-status">{{statusLabel(detailData)}}</text><view class="detail-amount"><text>¥</text>{{money(detailData.payerTotalCents??detailData.amountCents)}}</view><text class="detail-caption">{{amountLabel(detailData)}}</text></view>
     <view class="detail-product"><text>{{detailData.name}}</text><view v-if="detailData.kind==='points_recharge'&&detailData.product?.points!==undefined">{{detailData.product.points.toLocaleString()}} 积分<text v-if="detailData.product.bonus"> + 赠送 {{detailData.product.bonus.toLocaleString()}} 积分</text></view><view v-if="detailData.kind==='balance_recharge'&&detailData.product?.rechargeCents!==undefined">充值余额 ¥{{money(detailData.product.rechargeCents)}}<text v-if="detailData.product.bonusCents"> + 赠送 ¥{{money(detailData.product.bonusCents)}}</text></view><view v-if="['member','pack'].includes(detailData.kind||'')&&detailData.product?.quota!==undefined">原订单{{detailData.kind==='member'?'订阅':'积分包'}}额度 {{detailData.product.quota}}</view></view>
     <view class="detail-fields"><view><text>订单类型</text><text>{{orderKind(detailData)}}</text></view><view><text>订单编号</text><text>{{number(detailData)}}</text></view><view><text>创建时间</text><text>{{time(detailData.createdAt)}}</text></view><view><text>支付方式</text><text>{{paymentMethod(detailData)}}</text></view><view v-if="detailData.paidAt||detailData.payment?.paidAt"><text>支付时间</text><text>{{time((detailData.paidAt||detailData.payment?.paidAt)!)}}</text></view><view v-if="detailData.afterSale"><text>售后状态</text><text>{{states[detailData.afterSale.state]||'处理中'}}</text></view></view>
    </template>
    <template v-else>
     <view class="payment-result" :class="displayState"><view class="result-icon"><image :src="icon(result.icon)" mode="aspectFit"/></view><text class="result-title">{{result.title}}</text><text class="result-note">{{result.note}}</text><view class="detail-amount"><text>¥</text>{{money(detailData.payerTotalCents??detailData.amountCents)}}</view><text class="result-order">{{detailData.name}}</text></view>
     <view v-if="detailData.status==='pending'&&rechargeOrder" class="payment-options"><view class="payment-heading">{{switchIntent?'目标支付方式：'+targetMethod:'支付方式'}}</view><view v-if="methodsAction==='initial'" class="service-note" role="status">正在读取支付方式…</view><view v-if="methodsError" class="order-error" role="alert">{{methodsError}}<button role="button" :loading="methodsAction==='retry'" :disabled="!!methodsAction" @click="readMethods('retry')">重新读取支付方式</button></view><ClientPaymentMethods v-if="!switchIntent" v-model="method" :methods="demo?undefined:methods" :disabled="paying||querying||!!methodsAction||demo||paymentUnknown" :allow-balance="detailData.kind!=='balance_recharge'" :balance-cents="balanceCents"/><view v-if="!methodsAction&&!methodsError&&!methods.length&&!demo" class="service-note">当前没有可用的支付方式</view><view v-if="requiresSwitch&&!switchIntent" class="service-note">更换方式前会先确认原支付已关闭，订单编号与金额保持不变。</view><view v-if="switchIntent" class="service-note">{{paying?'正在确认原支付状态，请勿重复付款。':paymentUnknown?'切换结果尚未确认，请先重新查询原订单。':'已保留本次选择的支付方式，稍后可继续支付原订单。'}}<text v-if="!methodsAction&&switchReason"> {{switchReason}}</text></view></view>
     <view v-else class="payment-facts"><view><text>订单编号</text><text>{{number(detailData)}}</text></view><view><text>支付方式</text><text>{{paymentMethod(detailData)}}</text></view></view>
     <view v-if="(displayState==='pending'||displayState==='failed')&&(demo||!rechargeOrder)" class="service-note">{{demo?'演示订单不支持付款':'历史订单继续支付暂未开放'}}</view>
     <view v-if="payError" class="order-error" role="alert">{{payError}}</view>
    </template>
    <view v-if="detailData.fulfillment" class="payment-facts"><view><text>到账状态</text><text>{{({credited:'已到账',pending:'待到账',revoked:'已回收',compensation:'待补偿'} as Record<string,string>)[detailData.fulfillment]||'待核实'}}</text></view><view v-if="detailData.refundedCents"><text>累计退款</text><text>¥{{money(detailData.refundedCents)}}</text></view></view>
   </template>
   <template #footer><view v-if="detailData" class="sheet-actions"><button v-if="panel==='detail'" role="button" class="primary" :disabled="!!detailAction||paying||querying" @click="switchPanel('payment')">{{detailData.status==='pending'?'查看支付状态':'查看支付结果'}}</button><template v-else><button role="button" :disabled="!!detailAction||paying||querying" @click="switchPanel('detail')">订单详情</button><button v-if="['processing','unknown','switching'].includes(displayState)||switchIntent||methodsError" role="button" :loading="querying||detailAction==='query'" :disabled="paying||querying||!!detailAction" @click="queryCurrent">重新查询</button><button v-if="['pending','failed','switching'].includes(displayState)||paying" role="button" class="primary" :loading="paying" :aria-disabled="!canPay" :disabled="!canPay" @click="payCurrent">{{payLabel}}</button><button v-else-if="!['processing','unknown'].includes(displayState)" role="button" class="primary" @click="closeDetails">完成</button></template></view><button v-else role="button" class="sheet-close" @click="closeDetails">返回列表</button></template>
  </ClientDialog>
  <ClientDialog v-if="selected" title="申请退款" presentation="sheet" :busy="submitting" @close="cancel">
   <view class="refund-name">{{selected.name}}</view><textarea v-model="reason" :maxlength="200" :disabled="submitting" placeholder="请填写退款原因" aria-label="退款原因" class="refund-reason"/><view class="service-note">申请经商家审核后按原支付渠道处理，已使用的套餐需先核查。</view><view v-if="formError" class="order-error" role="alert">{{formError}}</view><template #footer><view class="sheet-actions"><button role="button" :disabled="submitting" @click="cancel">取消</button><button role="button" class="primary" :loading="submitting" :disabled="submitting" @click="submit">提交申请</button></view></template>
  </ClientDialog>
  <ClientDialog v-if="historyOrder" title="售后记录" presentation="sheet" @close="closeHistory">
   <view v-if="historyError" class="order-error" role="alert"><text>{{historyError}}</text><button role="button" :loading="!!historyBusy" :disabled="!!historyBusy" :aria-disabled="!!historyBusy" @click="retryHistory">重新加载</button></view>
   <view v-else-if="historyBusy" class="sheet-loading" role="status">正在读取售后记录…</view>
   <view v-else-if="!history?.length" class="sheet-loading">暂无售后记录</view>
   <view v-for="item in history||[]" :key="item.id" class="history-item">
    <view class="history-heading"><text>{{states[item.state]||'处理中'}}</text><text>{{time(item.createdAt)}}</text></view>
    <view class="detail-fields history-facts">
     <view><text>{{item.source==='consumer'?'申请退款金额':'本次退款金额'}}</text><text>{{refundAmount(item.requestedCents)}}</text></view>
     <view v-if="item.state==='SUCCESS'"><text>实际退款金额</text><text>{{refundAmount(item.payerRefundCents)}}</text></view>
     <view><text>退款渠道</text><text>{{paymentProvider(item.provider)}}</text></view>
     <view v-if="item.reviewedAt"><text>审核时间</text><text>{{time(item.reviewedAt)}}</text></view>
     <view v-if="item.state==='SUCCESS'&&item.succeededAt"><text>退款时间</text><text>{{time(item.succeededAt)}}</text></view>
    </view>
    <view class="history-copy">{{item.source==='consumer'?'申请原因':'退款原因'}}：{{item.reason}}</view><view v-if="item.reviewReason" class="history-copy">处理意见：{{item.reviewReason}}</view>
   </view>
   <template #footer><button role="button" class="sheet-close" @click="closeHistory">完成</button></template>
  </ClientDialog>
  <ClientDialog v-if="confirmation" :title="confirmation.kind==='delete'?'删除订单':'取消订单'" :busy="!!paymentAction" @close="closeAction"><view class="confirm-copy">{{confirmation.kind==='delete'?'删除后将不再显示在订单列表中，已获得的权益不受影响。':'确定取消这笔待支付订单吗？'}}</view><view class="confirm-order">{{confirmation.order.name}}</view><view v-if="actionError" class="order-error" role="alert">{{actionError}}</view><template #footer><view class="confirm-actions"><button role="button" :disabled="!!paymentAction" @click="closeAction">暂不{{confirmation.kind==='delete'?'删除':'取消'}}</button><button role="button" class="primary" :loading="!!paymentAction" :disabled="!!paymentAction" @click="confirmAction">确认{{confirmation.kind==='delete'?'删除':'取消'}}</button></view></template></ClientDialog>
 </view>
</template>
<style scoped>
.consumer-orders{display:flex;flex-direction:column;height:100dvh;max-width:480px;margin:auto;overflow:hidden;background:var(--client-page-background, #f3f9ff);color:var(--client-text,#203450);font:14px/1.6 -apple-system,BlinkMacSystemFont,'Segoe UI','Microsoft YaHei',sans-serif}.consumer-orders view,.consumer-orders button{box-sizing:border-box}.consumer-orders button{display:flex;align-items:center;justify-content:center;margin:0;padding:0 14px;min-height:36px;border:1px solid #dfe6f0;border-radius:9px;background:var(--client-surface,#fff);color:var(--client-muted,#718198);font:inherit;font-size:12px;line-height:1.5}.consumer-orders button::after{border:0}.consumer-orders button[disabled]{opacity:1}.consumer-orders button.primary{border-color:var(--client-primary,#3479f6);background:var(--client-primary,#3479f6);color:#fff}.consumer-orders button.primary[disabled]{border-color:var(--client-primary-disabled,#dce7fa);background:var(--client-primary-disabled,#dce7fa);color:#7892b6}.preview-mode{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:2px 18px 6px;font-size:11px;color:var(--client-muted)}.preview-mode button{min-width:100px;min-height:30px;padding:0;border:0;background:transparent;color:var(--client-primary);font-size:11px}.orders-scroll{flex:1;min-height:0;height:0}.order-body{padding:var(--client-content-top, 16px) var(--client-page-gutter, 10px) calc(24px + env(safe-area-inset-bottom))}.order-card{padding:15px;margin-top:12px;border:1px solid #e7edf6;border-radius:14px;background:var(--client-surface)}.order-heading{display:flex;justify-content:space-between;align-items:center;gap:12px}.order-kind{display:flex;align-items:center;gap:7px;min-width:0;color:var(--client-muted);font-size:11px}.order-kind image{width:17px;height:17px;flex-shrink:0}.order-status{font-size:11px;white-space:nowrap;color:var(--client-muted)}.order-status.pending{color:var(--client-primary)}.order-status.paid{color:#388366}.order-status.refunded{color:#5681bc}.order-purchase{display:flex;align-items:center;justify-content:space-between;gap:16px;margin-top:17px}.order-name{flex:1;min-width:0;font-size:15px;font-weight:600;overflow-wrap:anywhere}.order-price{display:flex;align-items:baseline;gap:2px;flex-shrink:0;font-size:23px;font-weight:650;font-variant-numeric:tabular-nums}.order-price>text{font-size:12px;font-weight:400}.order-meta{display:flex;justify-content:space-between;gap:12px;margin-top:8px;font-size:10px;color:var(--client-muted)}.order-actions{display:flex;justify-content:flex-end;align-items:center;gap:8px;flex-wrap:wrap;margin-top:16px;padding-top:13px;border-top:1px solid #eef1f6}.order-actions button{white-space:nowrap}.order-actions .detail-entry{margin-right:auto;min-width:82px}.order-sale-state{margin-top:10px;font-size:11px;color:var(--client-muted)}.order-empty{display:flex;align-items:center;flex-direction:column;gap:14px;padding:64px 16px;color:var(--client-muted);font-size:14px}.order-empty image{width:44px;height:44px;opacity:.4}.empty-note{font-size:12px}.pager{display:flex;align-items:center;gap:12px;margin-top:20px;font-size:12px;color:var(--client-muted)}.pager button{flex:1;min-width:0}.order-error{padding:12px 14px;margin:12px 0;border-radius:10px;background:#fff0ef;color:#b84039;font-size:13px;line-height:1.7}.order-error button{margin-top:8px;min-width:100px;color:#b84039;background:#ffe5e1;border:0}.order-notice{padding:12px 14px;margin:12px 0;border-radius:10px;background:#edf7f1;color:#388366;font-size:13px}.sheet-demo{font-size:10px;color:var(--client-muted);margin-bottom:8px}.sheet-loading{padding:48px 16px;text-align:center;color:var(--client-muted);font-size:13px}.detail-summary{text-align:center;padding:6px 0 22px}.detail-status{color:var(--client-primary);font-size:13px}.detail-amount{display:flex;align-items:baseline;justify-content:center;gap:3px;margin-top:10px;font-size:32px;font-weight:650;line-height:1.3;font-variant-numeric:tabular-nums}.detail-amount>text{font-size:15px;font-weight:400}.detail-caption{display:block;margin-top:6px;font-size:11px;color:var(--client-muted)}.detail-product{padding:15px;border-radius:10px;background:var(--client-background);font-size:14px;font-weight:600}.detail-product>view{margin-top:7px;font-size:12px;font-weight:400;color:var(--client-muted)}.detail-fields,.payment-facts{display:flex;flex-direction:column;gap:16px;padding-top:22px;font-size:12px}.detail-fields>view,.payment-facts>view{display:flex;justify-content:space-between;gap:18px}.detail-fields>view>text:first-child,.payment-facts>view>text:first-child{flex-shrink:0;color:var(--client-muted)}.detail-fields>view>text:last-child,.payment-facts>view>text:last-child{min-width:0;text-align:right;overflow-wrap:anywhere}.sheet-actions{display:flex;gap:12px}.sheet-actions button{flex:1;min-width:0;min-height:44px;padding:0;white-space:nowrap;font-size:14px}.consumer-orders .sheet-close{width:100%;min-height:42px;color:var(--client-primary)}.payment-result{display:flex;align-items:center;flex-direction:column;text-align:center;padding:8px 4px 18px}.result-icon{display:flex;align-items:center;justify-content:center;width:54px;height:54px;border-radius:17px;background:var(--client-primary-soft)}.result-icon image{width:31px;height:31px}.result-title{margin-top:16px;font-size:19px;font-weight:600}.result-note{margin-top:8px;font-size:12px;color:var(--client-muted);line-height:1.8;max-width:300px}.result-order{margin-top:9px;font-size:12px;color:var(--client-muted)}.payment-result .detail-amount{margin-top:22px}.payment-heading{font-size:14px;font-weight:600;padding-top:10px}.payment-facts{border-top:1px solid #edf1f6}.service-note{margin-top:16px;font-size:12px;line-height:1.8;color:var(--client-muted)}.payment-options+.service-note{text-align:center;font-size:11px}.refund-name{font-size:15px;font-weight:600}.refund-reason{width:100%;box-sizing:border-box;min-height:112px;margin:16px 0;padding:12px;border:1px solid #e3eaf5;background:var(--client-background);border-radius:10px;font-size:14px}.history-item{padding:14px 0;font-size:12px;color:var(--client-muted);line-height:1.8}.history-item+.history-item{border-top:1px solid #edf1f6}.history-heading{display:flex;flex-wrap:wrap;justify-content:space-between;gap:8px;margin-bottom:6px;color:var(--client-text)}.confirm-copy{font-size:14px;line-height:1.8;color:var(--client-muted)}.confirm-order{margin-top:14px;font-weight:600}.confirm-actions{display:flex;gap:12px;padding:16px 20px}.confirm-actions button{flex:1;min-width:0}@media(max-width:350px){.order-body{padding-inline:var(--client-page-gutter, 10px)}.order-card{padding:13px}.order-name{font-size:14px}.order-price{font-size:21px}.order-actions{gap:7px}.order-actions button{padding-inline:10px}}

.history-facts{gap:10px;padding:10px 0;color:var(--client-text)}.history-copy{margin-top:6px;overflow-wrap:anywhere;white-space:pre-wrap}
</style>
